package cn.servicehub.workflow.team;import java.sql.Timestamp;import java.util.Optional;import org.springframework.context.annotation.Profile;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;@Repository@Profile("mysql")public class MySqlSupportQueueReconciliationRepository implements SupportQueueReconciliationRepository{private final JdbcTemplate j;public MySqlSupportQueueReconciliationRepository(JdbcTemplate j){this.j=j;}public void create(SupportQueueReconciliationRequest r){j.update("INSERT INTO support_queue_idempotency_reconciliation_request(id,target_actor_iam_user_id,idempotency_key,command_version,decision,result_resource_type,result_resource_id,reason,status,requested_by_iam_user_id,version,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,0,?)",r.id(),r.targetActorIamUserId(),r.idempotencyKey(),r.commandVersion(),r.decision(),r.resultResourceType(),r.resultResourceId(),r.reason(),r.status(),r.requestedByIamUserId(),Timestamp.from(r.createdAt()));}public Optional<SupportQueueReconciliationRequest>find(String id){return j.query("SELECT * FROM support_queue_idempotency_reconciliation_request WHERE id=?",(s,n)->new SupportQueueReconciliationRequest(s.getString("id"),s.getString("target_actor_iam_user_id"),s.getString("idempotency_key"),s.getLong("command_version"),s.getString("decision"),s.getString("result_resource_type"),s.getString("result_resource_id"),s.getString("reason"),s.getString("status"),s.getString("requested_by_iam_user_id"),s.getString("approved_by_iam_user_id"),s.getLong("version"),s.getTimestamp("created_at").toInstant(),s.getTimestamp("decided_at")==null?null:s.getTimestamp("decided_at").toInstant()),id).stream().findFirst();}public boolean approve(SupportQueueReconciliationRequest r,long v){return j.update("UPDATE support_queue_idempotency_reconciliation_request SET status=?,approved_by_iam_user_id=?,decided_at=?,version=version+1 WHERE id=? AND version=? AND status='PENDING'",r.status(),r.approvedByIamUserId(),Timestamp.from(r.decidedAt()),r.id(),v)==1;}}
